import time

from taf.ul.trs_e2e_fw.lib.utils.string_format import decode_str

from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable

from taf.ul.trs_e2e_fw.lib.networking_devices.switch.SshConnection import SshConnection
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class TPSSsh(SshConnection):
    TOOL = "tps"

    def __init__(self, device, command_profile):
        super(TPSSsh, self).__init__(device, command_profile)
        self.tps_user = get_config_variable(["switch", device, "tps_user"])
        self.tps_password = get_config_variable(["switch", device, "tps_password"])

    def configure_switch(self, **kwargs):
        """
        Configure switch is used to manage the switch operations.
        It does following operations:
        1. Login to switch
        2. Execute various commands based on the command profiles present in the switch section of the testline config
        3. Logs out of the switch
         Args:
        max_retries: max number of retries to be done
        Returns:

        """
        logger.info("Configuring Switch via ssh..")
        try:
            self.login_to_switch()
            self.login_to_tps()
            self.execute_commands_and_verify()
        except Exception as e:
            raise e
        finally:
            self.close_connection()

    def login_to_tps(self):
        """
        Logs in to the TPS switch by using appropriate credentials from config variable.
        Raises:
            Exception: Raised when failed to execute command
        """
        self._ssh_execute_command(self.tps_user, prompt='Password: ')
        self._ssh_execute_command(self.tps_password, prompt="Do you acknowledge? (Y/N)?")
        self._ssh_execute_command("Y", prompt=self.enable_prompt)

    def _ssh_execute_command(self, command, prompt, timeout=30):
        """
        Execute commands on switch

        Args:
            command (str): command to be executed
            prompt (str): switch prompt

        Returns:
            None

        Raises:
            Exception: Raised when failed to execute command

        """
        try:
            self.ssh_shell.send(command + "\n")
            for i in range(timeout):
                output = self.ssh_shell.recv(65535)
                if prompt in decode_str(output):
                    return decode_str(output)
                time.sleep(1)
        except Exception as err:
            logger.error("{} Command execution failed : {}".format(command, err))
